#include "search.hpp"
#include "search_bloom.hpp"
#include "search_wire.hpp"
#include <fstream>
#include <iostream>
#include <set>
#include <stdexcept>
namespace rcm=biglybtc::services::related_content;
using biglybtc::core::Document;using biglybtc::core::Node;
namespace {
unsigned assertions=0;
void require(bool value,const std::string& message){++assertions;if(!value){throw std::runtime_error(message);}}
std::int64_t integer(const Node& node,std::string_view key){const auto* value=node.find(key);require(value&&value->type==Node::Type::Integer,"Generated integer");return value->integer;}
std::string bytes(const Node& node,std::string_view key){const auto* value=node.find(key);require(value&&value->type==Node::Type::Bytes,"Generated bytes");return std::string(value->bytes);}
rcm::Item item(int n){rcm::Item row;row.hash=std::string(20,char(n));row.title="generated alpha";row.packedPeers=(10<<16)|3;row.publishedHours=1000;row.version=n%2;row.randoms.resize(std::size_t(n));row.tags={"generated classics"};return row;}
void actualOriginal(const char* path){
 std::ifstream input(path,std::ios::binary);require(bool(input),"Original fixture available");const std::string raw{std::istreambuf_iterator<char>(input),{}};require(raw.size()<=1024*1024,"Bounded original fixture");auto doc=Document::parse(raw);require(bool(doc),"Original bencoded fixture");
 const auto* rows=doc->find("items"),*queries=doc->find("queries");require(rows&&queries&&rows->type==Node::Type::List&&queries->type==Node::Type::List,"Original corpus lists");const auto now=integer(doc->root(),"now");std::vector<rcm::Item> items;
 for(const auto& row:rows->children){const auto* wire=row.find("wire");require(wire,"Original association fixture");const auto rawWire=biglybtc::core::encodeValue(*wire);require(bool(rawWire),"Original wire encode");auto decoded=rcm::decodeAssociation(*rawWire,{},1,true,std::int32_t(now/1000));require(bool(decoded),"Actual native association decoder");const auto rank=integer(row,"rank");require(rank>=0&&rank<=100,"Generated original rank");decoded->randoms.resize(std::size_t(rank));auto words=rcm::searchWords(*decoded);require(bool(words),"Original Bloom word extraction");const auto* expectedWords=row.find("words");require(expectedWords&&expectedWords->type==Node::Type::List,"Original Bloom words");std::vector<std::string> expectedWordList;for(const auto& word:expectedWords->children){require(word.type==Node::Type::Bytes,"Original Bloom word bytes");expectedWordList.emplace_back(word.bytes);}require(*words==expectedWordList,"Original UTF16 Bloom words");items.push_back(std::move(*decoded));}
 const auto* bloomNode=doc->find("bloom");require(bloomNode,"Original search Bloom fixture");auto bloom=rcm::SearchBloom::decodeForRelatedSearch(*bloomNode);require(bool(bloom),"Original 50001-bit Bloom decode");require(!rcm::SearchBloom::decode(*bloomNode),"Chat quota remains independent");
 const auto* boundaryNode=doc->find("boundaryBloom");require(boundaryNode,"Original boundary Bloom");auto boundary=rcm::SearchBloom::decodeForRelatedSearch(*boundaryNode);require(boundary&&boundary->count()==6251,"Original all-Bloom one-word DHT tail accepted");
 auto exact=rcm::SearchBloom::createForRelatedSearch(50000);require(bool(exact),"Search Bloom allocation");for(const auto& item:items){auto words=rcm::searchWords(item);for(const auto& word:*words){exact->add(word);}}require(exact->count()==bloom->count()&&exact->map()==bloom->map(),"Byte-exact original search Bloom map/count");
 unsigned count=0;
 for(const auto& query:queries->children){const auto request=rcm::SearchRequest{bytes(query,"term"),std::int32_t(integer(query,"s")),std::int32_t(integer(query,"l")),std::int32_t(integer(query,"a"))};auto encodedRequest=rcm::encodeSearchRequest({rcm::SearchOperation::Query,request});require(encodedRequest&&*encodedRequest==bytes(query,"requestWire"),"Actual Java BEncoder query bytes");auto decodedRequest=rcm::decodeSearchRequest(*encodedRequest);require(decodedRequest&&decodedRequest->query.term==bytes(query,"normalised"),"Original query wire parse");const auto compiled=rcm::SearchQuery::compile(request);require(bool(compiled),"Original query compile case="+std::to_string(count));require(compiled->normalisedTerm()==bytes(query,"normalised"),"Original normalisation case="+std::to_string(count));auto bloomHit=rcm::bloomMayMatch(*bloom,*compiled);require(bloomHit&&*bloomHit==bool(integer(query,"bloom")),"Original foreign Bloom selection case="+std::to_string(count));const auto found=rcm::search(items,*compiled,false,now);require(bool(found),"Bounded native matching case="+std::to_string(count));std::set<std::string> actual,expected;for(const auto& value:*found){actual.insert(value.hash);}const auto* wanted=query.find("expected");require(wanted&&wanted->type==Node::Type::List,"Original hit set");for(const auto& hash:wanted->children){require(hash.type==Node::Type::Bytes&&hash.bytes.size()==20,"Original matched identity");expected.emplace(hash.bytes);}if(actual!=expected){for(const auto& item:items){if(actual.contains(item.hash)!=expected.contains(item.hash)){std::cerr<<"Generated differential case="<<count<<" item="<<item.title<<" original="<<expected.contains(item.hash)<<" native="<<actual.contains(item.hash)<<'\n';}}}require(actual==expected,"Original related-search hit set case="+std::to_string(count));++count;}
 const auto* handlers=doc->find("handlers");require(handlers&&handlers->children.size()==2,"Original migrated handler keys");for(unsigned i=0;i<2;++i){require(rcm::searchHandler(i!=0)==handlers->children[i].bytes,"Actual DDBaseHelpers SHA1 migration mapping");}
 auto response=rcm::decodeSearchResponse(bytes(doc->root(),"responseWire"));require(response&&response->items.size()==30,"Original Java search reply fields");for(std::size_t i=0;i<30;++i){require(response->items[i].hash==items[i].hash&&response->items[i].title==items[i].title&&response->items[i].randoms.size()==items[i].randoms.size(),"Original reply identity/title/rank");}auto roundtrip=rcm::encodeSearchResponse(*response);require(roundtrip&&*roundtrip==bytes(doc->root(),"responseWire"),"Byte-exact Java BEncoder search result wire");
 require(count==42,"Complete actual Java corpus consumed");std::cout<<"PASS_ORIGINAL_SEARCH_DIFFERENTIAL items="<<items.size()<<" queries="<<count<<'\n';
}
void controls(){
 rcm::SearchMessage fetch;fetch.operation=rcm::SearchOperation::FetchBloom;auto fetchBytes=rcm::encodeSearchRequest(fetch);require(fetchBytes&&*fetchBytes=="d1:x1:fe","Original fetch map");fetch.operation=rcm::SearchOperation::UpdateBloom;fetch.bloomCount=42;auto update=rcm::encodeSearchRequest(fetch);require(update&&*update=="d1:si42e1:x1:ue","Original update map");require(!rcm::decodeSearchRequest("d1:t1:a1:t1:be"),"Duplicate terms refused");require(!rcm::decodeSearchRequest("d1:x1:f1:t1:ae"),"Mixed operation refused");require(!rcm::encodeSearchRequest({rcm::SearchOperation::Query,{std::string(250,'q')}}),"Original 255 byte DATA key cap");
 rcm::SearchResponse empty;empty.resultsPresent=true;auto emptyWire=rcm::encodeSearchResponse(empty);require(emptyWire&&*emptyWire=="d1:llee","Original explicit empty result list");auto emptyReply=rcm::decodeSearchResponse(*emptyWire);require(emptyReply&&emptyReply->resultsPresent&&emptyReply->items.empty(),"Empty success is retained distinctly from absent results");
 rcm::SearchResponse bad;bad.items.resize(31);require(!rcm::encodeSearchResponse(bad),"Remote hit cap enforced");require(!rcm::decodeSearchResponse("d1:lli3eee"),"Malformed result refused");bad.items={item(1)};bad.items[0].tracker="https://synthetic.invalid/passkey-DO-NOT-PUBLISH";auto safe=rcm::encodeSearchResponse(bad);require(safe&&safe->find("DO-NOT-PUBLISH")==std::string::npos&&safe->find("synthetic.invalid")==std::string::npos,"Tracker URL/key never encoded into public search");
 auto row=item(1);const auto query=rcm::SearchQuery::compile({"alpha -beta"});require(bool(query),"Compile independent exclusion");require(query->matches(row,3600000000LL).value_or(false),"Positive term plus absent exclusion");row.title="alpha beta";require(!query->matches(row,3600000000LL).value_or(true),"Present exclusion refuses");
 const auto tagged=rcm::SearchQuery::compile({"tag:generated+cla"});require(tagged&&tagged->matches(row,3600000000LL).value_or(false),"Original encoded tag prefix");
 require(!rcm::SearchQuery::compile({std::string(1025,'a')}),"Term byte limit");require(!rcm::SearchQuery::compile({std::string("\xff",1)}),"Invalid UTF8 refused");const auto simple=rcm::SearchQuery::compile({"alpha"});require(bool(simple),"Simple query");
 std::vector<rcm::Item> rows;for(int n=1;n<=80;++n){rows.push_back(item(n));}const auto remote=rcm::search(rows,*simple,true,3600000000LL);require(remote&&remote->size()==30,"Original remote cap30");require(remote->front().randoms.size()==80&&remote->back().randoms.size()==51,"Remote cap retains strongest ranks");const auto popular=rcm::SearchQuery::compile({"(.)"});require(popular&&popular->popular(),"Original popularity sentinel");const auto local=rcm::search(rows,*popular,false,3600000000LL);require(local&&local->size()==50,"Original local popularity cap50");require(local->front().version==1,"Popularity prefers newer version");
 require(!rcm::search(rows,*simple,false,3600000000LL,rcm::MaximumItems+1),"Result resource bound");require(!rcm::search(rows,*simple,false,3600000000LL,100,std::chrono::milliseconds{0}),"Nonpositive work budget refused");auto generated=rcm::buildSearchBlooms(std::span<const rcm::Item>(rows).first(2),std::span<const rcm::Item>(rows).subspan(2),42);require(bool(generated),"Build both original search Bloom scopes");require(generated->all.contains("hash:"+rcm::base32(rows.back().hash)),"DHT-only word enters all Bloom");require(!generated->withoutDht.contains("hash:"+rcm::base32(rows.back().hash)),"Neighbour Bloom omits DHT-only word");require(generated->withoutDht.bits()==1001&&generated->all.bits()>=generated->withoutDht.bits(),"Each original Bloom sizes its own distinct word set");require(!rcm::SearchBloom::createForRelatedSearch(50002),"Search bit resource cap");
 row.title.assign(16385,'a');require(!simple->matches(row,3600000000LL),"Oversized candidate refuses rather than fabricating a hit");
}
}
int main(int argc,char** argv){try{require(argc==2,"Original generated fixture path required");actualOriginal(argv[1]);controls();std::cout<<"PASS_RELATED_SEARCH assertions="<<assertions<<'\n';return 0;}catch(const std::exception& error){std::cerr<<"FAIL_RELATED_SEARCH "<<error.what()<<'\n';return 1;}}
